BEGIN READ ONLY;
SELECT jsonb_build_object('kind','identity','database',current_database(),'organization',id,'title',title) FROM public.organizations WHERE id=3;
SELECT jsonb_build_object('kind','tenant_summary','occasions',count(*),'ticket_features',count(*) FILTER (WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(o.features,'[]')) f WHERE f->>'code'='ticket')),'layouts',count(*) FILTER (WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(o.features,'[]')) f WHERE f->>'code'='ticket' AND f->'layout' IS NOT NULL))) FROM public.occasions o WHERE organization=3;
SELECT jsonb_build_object('kind','product_type','occasion_id',o.id,'occasion_link',o.link,'occasion_title',o.title,'occasion_hidden',o.is_hidden,'id',pt.id,'type',pt.type,'title',pt.title,'products',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',p.id,'title',p.title,'data_short_title',p.data->>'short_title','column_title_short',p.title_short,'hidden',p.is_hidden,'order',p."order",'ordered_count',(SELECT count(*) FROM eshop.order_product_ticket opt WHERE opt.product=p.id)) ORDER BY p.id),'[]') FROM eshop.products p WHERE p.product_type=pt.id),'fields',(SELECT COALESCE(jsonb_agg(jsonb_build_object('field_id',ff.id,'field_title',ff.title,'field_type',ff.type,'hidden',ff.is_hidden,'ticket_field',ff.is_ticket_field,'form_id',fo.id,'form_title',fo.title,'form_open',fo.is_open,'same_occasion',fo.occasion=pt.occasion) ORDER BY ff.id),'[]') FROM public.form_fields ff JOIN public.forms fo ON fo.id=ff.form WHERE ff.product_type=pt.id)) FROM eshop.product_types pt JOIN public.occasions o ON o.id=pt.occasion WHERE o.organization=3 AND (pt.type IN ('food','taxi') OR EXISTS(SELECT 1 FROM public.form_fields ff JOIN public.forms fo ON fo.id=ff.form WHERE ff.product_type=pt.id AND NOT ff.is_hidden AND ff.is_ticket_field)) ORDER BY o.id,pt.id;
SELECT jsonb_build_object('kind','ticket_configuration','occasion_id',o.id,'occasion_link',o.link,'hidden',o.is_hidden,'ticket_enabled',f->'is_enabled','ticket_type',f->'ticket_type','feature_keys',(SELECT jsonb_agg(k ORDER BY k) FROM jsonb_object_keys(f) k),'schema',f->'layout'->'schemaVersion','templates',(SELECT jsonb_object_agg(t.key,jsonb_build_object('flow',t.value->'flow','elements',(SELECT jsonb_agg(jsonb_build_object('id',e->'id','binding',e->'binding','productTypeId',e->'productTypeId','label',e->'label','visible',e->'visible') ORDER BY n) FROM jsonb_array_elements(t.value->'elements') WITH ORDINALITY a(e,n)))) FROM jsonb_each(COALESCE(f->'layout'->'templates','{}')) t)) FROM public.occasions o CROSS JOIN LATERAL jsonb_array_elements(COALESCE(o.features,'[]')) f WHERE o.organization=3 AND f->>'code'='ticket' ORDER BY o.id;
SELECT jsonb_build_object('kind','shared_renderer_summary','organization',o.organization,'ticket_features',count(*),'implicit_layouts',count(*) FILTER(WHERE f->'layout' IS NULL),'schemas',jsonb_agg(DISTINCT f->'layout'->'schemaVersion')) FROM public.occasions o CROSS JOIN LATERAL jsonb_array_elements(COALESCE(o.features,'[]')) f WHERE f->>'code'='ticket' GROUP BY o.organization ORDER BY o.organization;
COMMIT;
